-- Initial schema migration for Neon development. All statements are idempotent.
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_profiles (user_id text PRIMARY KEY, display_name text, avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id text NOT NULL, name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_members (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id text NOT NULL, role text NOT NULL CHECK (role IN ('owner','admin','editor','viewer')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (workspace_id,user_id));
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, owner_user_id text NOT NULL, title text NOT NULL, description text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','archived')), default_language text NOT NULL DEFAULT 'id', target_platforms text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, url text, title text NOT NULL, source_type text NOT NULL DEFAULT 'url', excerpt text, retrieved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, created_by text NOT NULL, topic text NOT NULL, audience text, language text NOT NULL DEFAULT 'id', report jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, created_by text NOT NULL, title text NOT NULL, hook text, outline jsonb NOT NULL DEFAULT '[]', body text NOT NULL DEFAULT '', call_to_action text, target_duration_seconds integer CHECK (target_duration_seconds IS NULL OR target_duration_seconds > 0), language text NOT NULL DEFAULT 'id', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','review','approved','published')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, owner_user_id text NOT NULL, bucket_name text NOT NULL DEFAULT 'studio-media-private', object_key text NOT NULL, media_type text NOT NULL, mime_type text, file_size_bytes bigint CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0), duration_seconds numeric(12,3), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(bucket_name,object_key));
CREATE TABLE IF NOT EXISTS generation_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, requested_by text NOT NULL, job_type text NOT NULL, provider text, model text, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','cancelled')), input jsonb NOT NULL DEFAULT '{}', output jsonb NOT NULL DEFAULT '{}', error_code text, error_message text, estimated_cost numeric(14,6) NOT NULL DEFAULT 0, actual_cost numeric(14,6) NOT NULL DEFAULT 0, started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clip_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, media_asset_id uuid REFERENCES media_assets(id) ON DELETE SET NULL, start_seconds numeric(12,3) NOT NULL CHECK (start_seconds >= 0), end_seconds numeric(12,3) NOT NULL CHECK (end_seconds > start_seconds), score numeric(6,3), rationale text, status text NOT NULL DEFAULT 'suggested' CHECK (status IN ('suggested','selected','rejected','rendered')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS caption_tracks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, media_asset_id uuid REFERENCES media_assets(id) ON DELETE CASCADE, language text NOT NULL DEFAULT 'id', format text NOT NULL CHECK (format IN ('srt','vtt','json')), content text NOT NULL, is_burned_in boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seo_metadata (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, platform text NOT NULL, title text, description text, tags text[] NOT NULL DEFAULT '{}', hashtags text[] NOT NULL DEFAULT '{}', thumbnail_asset_id uuid REFERENCES media_assets(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,platform));
CREATE TABLE IF NOT EXISTS social_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id text NOT NULL, platform text NOT NULL, platform_account_id text, account_label text, scopes text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','connected','expired','revoked','error')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS oauth_tokens (social_account_id uuid PRIMARY KEY REFERENCES social_accounts(id) ON DELETE CASCADE, encrypted_access_token text NOT NULL, encrypted_refresh_token text, expires_at timestamptz, encryption_key_version text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS social_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, social_account_id uuid REFERENCES social_accounts(id) ON DELETE SET NULL, created_by text NOT NULL, platform text NOT NULL, caption text, media_asset_ids uuid[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','scheduled','publishing','published','failed','cancelled')), external_post_id text, published_url text, scheduled_at timestamptz, published_at timestamptz, error_message text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id text NOT NULL, project_id uuid REFERENCES projects(id) ON DELETE SET NULL, job_id uuid REFERENCES generation_jobs(id) ON DELETE SET NULL, provider text, model text, usage_type text NOT NULL, quantity numeric(18,6) NOT NULL DEFAULT 0, unit text NOT NULL DEFAULT 'request', cost numeric(14,6) NOT NULL DEFAULT 0, currency char(3) NOT NULL DEFAULT 'USD', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, workspace_id uuid REFERENCES workspaces(id) ON DELETE SET NULL, actor_user_id text, action text NOT NULL, resource_type text NOT NULL, resource_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_projects_workspace_updated ON projects(workspace_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_project_created ON generation_jobs(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON generation_jobs(status,created_at);
CREATE INDEX IF NOT EXISTS idx_assets_project_created ON media_assets(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_posts_status_schedule ON social_posts(status,scheduled_at);
CREATE INDEX IF NOT EXISTS idx_usage_workspace_created ON usage_ledger(workspace_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_workspace_created ON audit_logs(workspace_id,created_at DESC);
INSERT INTO schema_migrations (version) VALUES ('0001_initial_schema') ON CONFLICT (version) DO NOTHING;
